'use client';

import {
  AnimatePresence,
  LayoutGroup,
  motion,
  type Transition,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { ArrowRightToLineIcon } from '@/registry/ndeko/lib/icons';

import { RollingCount } from './_parts/motion-parts';
import { keyOf } from './_parts/subtask-data';
import { StatusGlyph } from './_parts/subtask-parts';

type NoteLine = {
  id: string;
  text: string;
};

type ConvertedLine = NoteLine & {
  number: number;
};

const NOTES: NoteLine[] = [
  { id: 'n1', text: 'Finance wants the invoice number as the first column' },
  { id: 'n2', text: 'Amounts keep two decimals, with a dot' },
  { id: 'n3', text: 'Empty exports still download a header row' },
  { id: 'n4', text: 'Name the file after the date range' },
];

const FIRST_NUMBER = 231;

const TRAVEL: Transition = { type: 'spring', bounce: 0, duration: 0.35 };

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return TRAVEL;
}

function layoutIdOf(line: NoteLine, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return undefined;
  }
  return `line-${line.id}`;
}

function NoteRow({
  line,
  onConvert,
}: {
  line: NoteLine;
  onConvert: (isFromKeyboard: boolean) => void;
}) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.li
      layout='position'
      layoutId={layoutIdOf(line, shouldReduceMotion)}
      transition={travelOf(shouldReduceMotion)}
      className='group/row hover:bg-foreground/[0.03] flex min-h-9 items-center gap-3 rounded-lg ps-2.5 pe-1'
    >
      <span
        aria-hidden='true'
        className='bg-foreground/30 size-1 shrink-0 rounded-full'
      />
      <span className='min-w-0 flex-1 text-[13px] leading-5'>{line.text}</span>
      <button
        type='button'
        onClick={(event) => onConvert(event.detail === 0)}
        aria-label={`Make "${line.text}" a sub-task`}
        className='text-muted-foreground hover:bg-foreground/5 hover:text-foreground focus-visible:ring-ring/25 inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-md px-2 text-xs font-medium opacity-0 transition-[opacity,background-color,color] outline-none group-focus-within/row:opacity-100 group-hover/row:opacity-100 focus-visible:ring-[3px] pointer-coarse:opacity-100'
      >
        <ArrowRightToLineIcon className='size-3.5 rotate-90' />
        Sub-task
      </button>
    </motion.li>
  );
}

function SubtaskRow({ line }: { line: ConvertedLine }) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.li
      layout='position'
      layoutId={layoutIdOf(line, shouldReduceMotion)}
      transition={travelOf(shouldReduceMotion)}
      className='flex min-h-9 items-center gap-3 rounded-lg px-2.5'
    >
      <StatusGlyph status='todo' />
      <span className='text-muted-foreground w-16 shrink-0 text-xs tabular-nums'>
        {keyOf(line.number)}
      </span>
      <span className='min-w-0 flex-1 text-[13px] leading-5'>{line.text}</span>
    </motion.li>
  );
}

export default function Subtask07() {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [notes, setNotes] = useState(NOTES);
  const [converted, setConverted] = useState<ConvertedLine[]>([]);
  const [announcement, setAnnouncement] = useState('');
  const [focusIndex, setFocusIndex] = useState<number | null>(null);
  const notesRef = useRef<HTMLUListElement>(null);
  const hasNotes = notes.length > 0;
  const hasConverted = converted.length > 0;

  useEffect(() => {
    if (focusIndex === null) {
      return;
    }
    const buttons = notesRef.current?.querySelectorAll('button');
    if (!buttons) {
      return;
    }
    const lastIndex = buttons.length - 1;
    const target = buttons[Math.min(focusIndex, lastIndex)];
    target?.focus();
  }, [focusIndex, notes]);

  function convert(line: NoteLine, isFromKeyboard: boolean) {
    const number = FIRST_NUMBER + converted.length;
    if (isFromKeyboard) {
      const index = notes.findIndex((item) => item.id === line.id);
      setFocusIndex(index);
    }
    setNotes((current) => current.filter((item) => item.id !== line.id));
    setConverted((current) => [...current, { ...line, number }]);
    setAnnouncement(`${line.text} is now sub-task ${keyOf(number)}`);
  }

  return (
    <LayoutGroup>
      <section aria-label='Notes and sub-tasks' className='w-full max-w-md'>
        <motion.h3
          layout='position'
          transition={travelOf(shouldReduceMotion)}
          className='px-2.5 text-sm font-medium'
        >
          Notes
        </motion.h3>
        <ul ref={notesRef} className='mt-1.5'>
          {notes.map((line) => (
            <NoteRow
              key={line.id}
              line={line}
              onConvert={(isFromKeyboard) => convert(line, isFromKeyboard)}
            />
          ))}
        </ul>
        <AnimatePresence initial={false}>
          {!hasNotes && (
            <motion.p
              layout='position'
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className='text-muted-foreground px-2.5 py-2 text-[13px]'
            >
              Every note is a sub-task now
            </motion.p>
          )}
        </AnimatePresence>
        <motion.div
          layout='position'
          transition={travelOf(shouldReduceMotion)}
          className='mt-5 flex items-baseline justify-between gap-3 px-2.5'
        >
          <h3 className='text-sm font-medium'>Sub-tasks</h3>
          <span className='text-muted-foreground text-xs'>
            <RollingCount value={converted.length} /> created from notes
          </span>
        </motion.div>
        <ul className='mt-1.5'>
          {converted.map((line) => (
            <SubtaskRow key={line.id} line={line} />
          ))}
        </ul>
        {!hasConverted && (
          <p className='hairline-border border-foreground/20 text-muted-foreground mt-1.5 rounded-lg border-dashed px-3 py-2.5 text-[13px]'>
            Turn a note into a sub-task with the button on its line
          </p>
        )}
        <p aria-live='polite' className='sr-only'>
          {announcement}
        </p>
      </section>
    </LayoutGroup>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

